(()=>{'use strict';const $=id=>document.getElementById(id),allowed=['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','video/quicktime','application/pdf','audio/webm','audio/mp4'];let selected=[],xhr=null,running=false,cancelled=false;const status=t=>$('media-status').textContent=t,size=n=>(n/1024/1024).toFixed(1)+' MB';function choose(files){if(running)return;selected=Array.from(files).slice(0,20);$('media-queue').textContent=selected.map(f=>f.name+' · '+size(f.size)+(allowed.includes(f.type)&&f.size>0&&f.size<=50*1024*1024?'':' · Unsupported format or size')).join(' / ');status(selected.length+' files selected. Upload to save them to your account.');}function node(tag,text){const e=document.createElement(tag);if(text)e.textContent=text;return e;}
async function refresh(){try{const r=await fetch('/api/designer/media'),data=await r.json();if(!r.ok)throw Error(data.error);const host=$('media-files');host.replaceChildren();if(!data.files.length)host.append(node('p','No uploaded files yet.'));for(const f of data.files){const card=node('article'),title=node('h3',f.name);card.className='record';card.append(title);if(f.content_type.startsWith('image/')){const image=node('img');image.src=f.url;image.alt=f.name;image.loading='lazy';image.style.cssText='width:100%;max-height:240px;object-fit:contain';card.append(image);}else if(f.content_type.startsWith('video/')){const video=node('video');video.src=f.url;video.controls=true;video.preload='metadata';video.style.width='100%';card.append(video);}else if(f.content_type.startsWith('audio/')){const audio=node('audio');audio.controls=true;audio.src=f.url;card.append(audio);}card.append(node('p',size(f.size)+' · '+new Date(f.created_at).toLocaleString()));const open=node('a','Open file');open.href=f.url;open.target='_blank';open.rel='noopener';card.append(open);const attach=node('button','Use in creative project');attach.onclick=()=>{const input=document.querySelector('#designer-studio-form [name="url"]');input.value=new URL(f.url,location.origin).href;location.hash='my-studio';status('File attached to the creative project form. Save the project to keep the link.');};card.append(attach);const placement=node('button','Place on my website');placement.onclick=()=>{location.hash='storefront-editor';};card.append(placement);if(f.content_type.startsWith('image/')){const edit=node('button','Crop & rotate');edit.onclick=()=>document.dispatchEvent(new CustomEvent('media-edit-image',{detail:f}));card.append(edit);}const del=node('button','Delete file');del.onclick=async()=>{if(!confirm('Delete '+f.name+'? Saved project links to this file will stop working.'))return;del.disabled=true;try{const r=await fetch(f.url,{method:'DELETE'}),d=await r.json();if(!r.ok)throw Error(d.error);await refresh();status('File deleted.');}catch(e){status(e.message);del.disabled=false;}};card.append(del);host.append(card);}}catch(e){status(e.message||'File library unavailable. Retry shortly.');}}
function upload(f){return new Promise((resolve,reject)=>{xhr=new XMLHttpRequest();xhr.open('POST','/api/designer/media');xhr.setRequestHeader('Content-Type',f.type);xhr.setRequestHeader('X-File-Name',encodeURIComponent(f.name));xhr.timeout=300000;xhr.upload.onprogress=e=>{if(e.lengthComputable)$('media-progress').value=Math.round(e.loaded/e.total*100);};xhr.onload=()=>{let data;try{data=JSON.parse(xhr.responseText);}catch{reject(Error('Upload returned an unexpected response.'));return;}xhr.status>=200&&xhr.status<300?resolve(data):reject(Error(data.error||'Upload failed.'));};xhr.onerror=()=>reject(Error('Connection lost. Refresh the library before retrying.'));xhr.ontimeout=()=>reject(Error('Upload timed out. Refresh the library before retrying.'));xhr.onabort=()=>reject(Error('Upload cancelled. Refresh the library to check whether it finished.'));xhr.send(f);});}
$('media-input').onchange=e=>choose(e.target.files);for(const event of ['dragover','drop'])$('media-drop').addEventListener(event,e=>{e.preventDefault();if(event==='drop')choose(e.dataTransfer.files);});$('media-upload').onclick=async()=>{if(running)return;if(!selected.length){status('Choose files first.');return;}running=true;cancelled=false;$('media-upload').disabled=true;$('media-cancel').hidden=false;$('media-progress').hidden=false;let saved=0;const failed=[];for(const f of selected){if(cancelled)break;if(!allowed.includes(f.type)||!f.size||f.size>50*1024*1024){failed.push(f.name);continue;}status('Uploading '+f.name+'…');$('media-progress').value=0;try{await upload(f);saved++;}catch(e){failed.push(f.name);status(e.message);if(cancelled)break;}}running=false;xhr=null;$('media-upload').disabled=false;$('media-cancel').hidden=true;$('media-progress').hidden=true;await refresh();status(saved+' files saved.'+(failed.length?' Not saved: '+failed.join(', ')+'. Select those files again to retry.':'')+(cancelled?' Upload stopped. Refresh before retrying.':''));selected=[];$('media-input').value='';$('media-queue').textContent='';};$('media-cancel').onclick=()=>{cancelled=true;xhr?.abort();};$('media-refresh').onclick=refresh;window.addEventListener('beforeunload',e=>{if(running){e.preventDefault();e.returnValue='';}});refresh();})();
